def count_zeros(number):
    s = str(number)
    return s.count('0')

def calculate_A(M, N):
    if N == 0:
        return -1
    Q = M // N
    return count_zeros(Q)

# M must be a number with non-zero digits.
# Test small M (5 digits) against small N (1 to 9)
M_candidates = [
    11111,  # Smallest
    99999,  # Largest
    12345,
    55555,
    91111   # A case that might generate some zeros
]

N_values = list(range(1, 10))

results = {}

for M in M_candidates:
    results[M] = {}
    for N in N_values:
        A = calculate_A(M, N)
        results[M][N] = A

print("--- Empirical Results (5-Digit M) ---")
for M, data in results.items():
    print(f"M = {M}:")
    for N, A in data.items():
        print(f"  N = {N}: A = {A}")

# Check the implication for N=1
print("\n--- Specific Check for N=1 ---")
for M in M_candidates:
    A_n1 = calculate_A(M, 1)
    print(f"M = {M}, N = 1: A = {A_n1}")
